{
  "id": "solid.extrude",
  "input": {
    "$defs": {
      "AngleExpr": {
        "anyOf": [
          {
            "exclusiveMaximum": 1000000000.0,
            "exclusiveMinimum": -1000000000.0,
            "type": "number"
          },
          {
            "maxLength": 4096,
            "minLength": 1,
            "pattern": "[^\\u0009-\\u000d\\u0020\\u0085\\u00a0\\u1680\\u2000-\\u200a\\u2028-\\u2029\\u202f\\u205f\\u3000]",
            "type": "string"
          }
        ],
        "description": "An angle: a number of degrees, or an expression such as \"30 deg\" or \"a / 2\"."
      },
      "Direction": {
        "description": "Which way to extrude: positive (the default), negative, or symmetric (the distance is the total thickness, split evenly around the start plane). one_side is an alias of positive; reverse and flip of negative. Matching ignores case.",
        "enum": [
          "positive",
          "negative",
          "symmetric",
          "one_side",
          "reverse",
          "flip"
        ],
        "type": "string"
      },
      "ExtentKeyword": {
        "description": "\"through_all\" (any case) is the same as through_all: true.",
        "enum": [
          "through_all"
        ],
        "type": "string"
      },
      "ExtrudeConvention": {
        "description": "total_distance (the default): a symmetric distance is the total thickness. legacy_per_side keeps older designs' per-side meaning.",
        "enum": [
          "total_distance",
          "legacy_per_side"
        ],
        "type": "string"
      },
      "ExtrudeOperation": {
        "description": "How the extrusion combines with existing bodies: auto (cut into a body, otherwise join; new in an empty component), new, join, cut or intersect. The others are aliases. Matching ignores case, spaces, '_' and '-' (only case for auto).",
        "enum": [
          "auto",
          "new",
          "join",
          "cut",
          "intersect",
          "new_body",
          "newbody",
          "new_component",
          "newcomponent",
          "union",
          "add",
          "subtract",
          "difference",
          "intersection"
        ],
        "type": "string"
      },
      "Faces": {
        "description": "Points in mm, one on each of the coplanar faces of one body to extrude together.",
        "items": {
          "$ref": "#/$defs/Point3"
        },
        "maxItems": 1024,
        "minItems": 1,
        "type": "array"
      },
      "IdOrName": {
        "description": "A feature's id (a number) or its name.",
        "type": [
          "number",
          "string"
        ]
      },
      "LengthExpr": {
        "anyOf": [
          {
            "exclusiveMaximum": 1000000000.0,
            "exclusiveMinimum": -1000000000.0,
            "type": "number"
          },
          {
            "maxLength": 4096,
            "minLength": 1,
            "pattern": "[^\\u0009-\\u000d\\u0020\\u0085\\u00a0\\u1680\\u2000-\\u200a\\u2028-\\u2029\\u202f\\u205f\\u3000]",
            "type": "string"
          }
        ],
        "description": "A length: a number in the design's length unit, or an expression such as \"w / 2\" or \"30 mm\"."
      },
      "Point2": {
        "anyOf": [
          {
            "items": {
              "exclusiveMaximum": 1000000000.0,
              "exclusiveMinimum": -1000000000.0,
              "type": "number"
            },
            "maxItems": 2,
            "minItems": 2,
            "type": "array"
          },
          {
            "properties": {
              "x": {
                "exclusiveMaximum": 1000000000.0,
                "exclusiveMinimum": -1000000000.0,
                "type": "number"
              },
              "y": {
                "exclusiveMaximum": 1000000000.0,
                "exclusiveMinimum": -1000000000.0,
                "type": "number"
              }
            },
            "required": [
              "x",
              "y"
            ],
            "type": "object"
          }
        ],
        "description": "A sketch point in mm: [x, y] or {\"x\", \"y\"}."
      },
      "Point3": {
        "anyOf": [
          {
            "items": {
              "exclusiveMaximum": 1000000000.0,
              "exclusiveMinimum": -1000000000.0,
              "type": "number"
            },
            "maxItems": 3,
            "minItems": 3,
            "type": "array"
          },
          {
            "properties": {
              "x": {
                "exclusiveMaximum": 1000000000.0,
                "exclusiveMinimum": -1000000000.0,
                "type": "number"
              },
              "y": {
                "exclusiveMaximum": 1000000000.0,
                "exclusiveMinimum": -1000000000.0,
                "type": "number"
              },
              "z": {
                "exclusiveMaximum": 1000000000.0,
                "exclusiveMinimum": -1000000000.0,
                "type": "number"
              }
            },
            "required": [
              "x",
              "y",
              "z"
            ],
            "type": "object"
          }
        ],
        "description": "A point in mm: [x, y, z] or {\"x\", \"y\", \"z\"}."
      },
      "Profiles": {
        "anyOf": [
          {
            "pattern": "^[Aa][Ll][Ll]$",
            "type": "string"
          },
          {
            "maximum": 18446744073709551615,
            "minimum": 0,
            "type": "integer"
          },
          {
            "items": {
              "maximum": 18446744073709551615,
              "minimum": 0,
              "type": "integer"
            },
            "maxItems": 10000,
            "minItems": 1,
            "type": "array"
          },
          {
            "items": {
              "properties": {
                "point": {
                  "$ref": "#/$defs/Point2"
                }
              },
              "required": [
                "point"
              ],
              "type": "object"
            },
            "maxItems": 10000,
            "minItems": 1,
            "type": "array"
          },
          {
            "items": {
              "anyOf": [
                {
                  "items": {
                    "type": "string"
                  },
                  "minItems": 1,
                  "type": "array"
                },
                {
                  "properties": {
                    "curves": {
                      "anyOf": [
                        {
                          "type": "string"
                        },
                        {
                          "items": {
                            "type": "string"
                          },
                          "minItems": 1,
                          "type": "array"
                        }
                      ]
                    }
                  },
                  "required": [
                    "curves"
                  ],
                  "type": "object"
                },
                {
                  "not": {
                    "required": [
                      "curves"
                    ]
                  },
                  "properties": {
                    "loops": {
                      "items": {
                        "properties": {
                          "curves": {
                            "anyOf": [
                              {
                                "type": "string"
                              },
                              {
                                "items": {
                                  "type": "string"
                                },
                                "minItems": 1,
                                "type": "array"
                              }
                            ]
                          },
                          "outer": {
                            "type": "boolean"
                          }
                        },
                        "required": [
                          "curves"
                        ],
                        "type": "object"
                      },
                      "minItems": 1,
                      "type": "array"
                    }
                  },
                  "required": [
                    "loops"
                  ],
                  "type": "object"
                }
              ]
            },
            "maxItems": 10000,
            "minItems": 1,
            "not": {
              "items": {
                "required": [
                  "point"
                ],
                "type": "object"
              }
            },
            "type": "array"
          },
          {
            "anyOf": [
              {
                "properties": {
                  "type": {
                    "enum": [
                      "whole_boundaries"
                    ]
                  }
                },
                "required": [
                  "type"
                ],
                "type": "object"
              },
              {
                "not": {
                  "properties": {
                    "type": {
                      "enum": [
                        "whole_boundaries"
                      ]
                    }
                  },
                  "required": [
                    "type"
                  ]
                },
                "properties": {
                  "offset_boundaries": {
                    "items": {
                      "maxLength": 512,
                      "minLength": 1,
                      "type": "string"
                    },
                    "maxItems": 128,
                    "minItems": 1,
                    "type": "array",
                    "uniqueItems": true
                  }
                },
                "required": [
                  "offset_boundaries"
                ],
                "type": "object"
              },
              {
                "not": {
                  "required": [
                    "offset_boundaries"
                  ]
                },
                "properties": {
                  "associations": {
                    "items": {
                      "maxLength": 512,
                      "minLength": 1,
                      "type": "string"
                    },
                    "maxItems": 128,
                    "minItems": 1,
                    "type": "array",
                    "uniqueItems": true
                  },
                  "type": {
                    "enum": [
                      "offset_boundaries"
                    ]
                  }
                },
                "required": [
                  "type",
                  "associations"
                ],
                "type": "object"
              }
            ],
            "description": "Internal selections written by the app."
          }
        ],
        "description": "Which sketch profiles to use: \"all\" (the default, any case), an index, or a list of indices, of {\"point\": [x, y]} inside a profile, or of curve selections (a list of curve ids, {\"curves\": [ids]} or {\"loops\": [...]}). Picks by index or point are stored by the curves around the profile."
      },
      "StringList": {
        "anyOf": [
          {
            "type": "string"
          },
          {
            "items": {
              "type": "string"
            },
            "maxItems": 10000,
            "type": "array"
          }
        ],
        "description": "A name, or a list of names."
      },
      "ThinSide": {
        "description": "Which side of the curves the wall lies on: center (the default), inside, outside or two_sides. The others are aliases. Matching ignores case and surrounding spaces, and reads ' ' and '-' as '_'.",
        "enum": [
          "center",
          "inside",
          "outside",
          "two_sides",
          "centre",
          "centered",
          "centred",
          "symmetric",
          "side1",
          "side_1",
          "side2",
          "side_2",
          "both"
        ],
        "type": "string"
      }
    },
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "additionalProperties": false,
    "description": "Extrude sketch profiles (or a planar body face) into a solid.",
    "properties": {
      "body": {
        "default": null,
        "description": "With `face`, among placed instances: the body whose placement `face` is read in (read by\nthe engine's frame mapping, before the command runs). Default: `face_body`, else the\nbody nearest the point.",
        "type": [
          "string",
          "null"
        ]
      },
      "body_name": {
        "default": null,
        "description": "The new body's name.",
        "type": [
          "string",
          "null"
        ]
      },
      "body_names": {
        "anyOf": [
          {
            "$ref": "#/$defs/StringList"
          },
          {
            "type": "null"
          }
        ],
        "description": "Names for the new bodies, in order."
      },
      "convention": {
        "$ref": "#/$defs/ExtrudeConvention",
        "description": "How a symmetric distance is read. Default: total_distance."
      },
      "curves": {
        "anyOf": [
          {
            "$ref": "#/$defs/StringList"
          },
          {
            "type": "null"
          }
        ],
        "description": "With `thin`: the curves the wall follows. Default: every drawn curve of the sketch."
      },
      "direction": {
        "anyOf": [
          {
            "$ref": "#/$defs/Direction"
          },
          {
            "type": "null"
          }
        ],
        "description": "Which way to extrude. Default: positive."
      },
      "distance": {
        "anyOf": [
          {
            "$ref": "#/$defs/LengthExpr"
          },
          {
            "type": "null"
          }
        ],
        "description": "How far: the length one way; with `direction: symmetric`, the total thickness (per side\nwith `convention: legacy_per_side`); with `distance2`, the first side's length. Required\nunless `through_all` or `to` is given."
      },
      "distance2": {
        "anyOf": [
          {
            "$ref": "#/$defs/LengthExpr"
          },
          {
            "type": "null"
          }
        ],
        "description": "Two Sides: a second distance the other way from the first side, which may be\n`through_all` or `to`; with `direction: negative` the first side goes against the normal\nand `distance2` along it."
      },
      "extent": {
        "anyOf": [
          {
            "$ref": "#/$defs/ExtentKeyword"
          },
          {
            "type": "null"
          }
        ],
        "description": "`\"through_all\"`, the same as `through_all: true`."
      },
      "face": {
        "anyOf": [
          {
            "$ref": "#/$defs/Point3"
          },
          {
            "type": "null"
          }
        ],
        "description": "A point on a planar body face to extrude instead of a sketch profile."
      },
      "face_body": {
        "default": null,
        "description": "The body whose face to use, where faces of several bodies meet at `face` (or `faces`).",
        "type": [
          "string",
          "null"
        ]
      },
      "faces": {
        "$ref": "#/$defs/Faces",
        "description": "Several coplanar faces of one body to extrude together, by a point on each. Not with\n`face`, `sketch` or `profiles`."
      },
      "from": {
        "$ref": "#/$defs/Point3",
        "description": "Start at this face or point (From Object)."
      },
      "name": {
        "default": null,
        "description": "The feature's name in the timeline.",
        "type": [
          "string",
          "null"
        ]
      },
      "operation": {
        "anyOf": [
          {
            "$ref": "#/$defs/ExtrudeOperation"
          },
          {
            "type": "null"
          }
        ],
        "description": "How the extrusion combines with existing bodies. Default: new."
      },
      "participants": {
        "anyOf": [
          {
            "$ref": "#/$defs/StringList"
          },
          {
            "type": "null"
          }
        ],
        "description": "The bodies taking part; overrides the default scope."
      },
      "profiles": {
        "$ref": "#/$defs/Profiles",
        "description": "Which of the sketch's profiles to extrude. Default: all of them. Ignored when `face` is\ngiven; not allowed with `thin`."
      },
      "side": {
        "anyOf": [
          {
            "$ref": "#/$defs/ThinSide"
          },
          {
            "type": "null"
          }
        ],
        "description": "With `thin`: which side of the curves the wall lies on. Default: center."
      },
      "sketch": {
        "$ref": "#/$defs/IdOrName",
        "description": "The sketch to extrude, by id or name. Default: the active sketch, else the last one.\nIgnored when `face` is given."
      },
      "start_offset": {
        "anyOf": [
          {
            "$ref": "#/$defs/LengthExpr"
          },
          {
            "type": "null"
          }
        ],
        "description": "Start this far from the sketch plane, along its normal."
      },
      "taper": {
        "anyOf": [
          {
            "$ref": "#/$defs/AngleExpr"
          },
          {
            "type": "null"
          }
        ],
        "description": "Draft angle of the side walls."
      },
      "targets": {
        "anyOf": [
          {
            "$ref": "#/$defs/StringList"
          },
          {
            "type": "null"
          }
        ],
        "description": "The bodies a join, cut or intersect works on. Default for a join from a body's face:\nthat body."
      },
      "thickness": {
        "anyOf": [
          {
            "$ref": "#/$defs/LengthExpr"
          },
          {
            "type": "null"
          }
        ],
        "description": "With `thin`: the wall's thickness."
      },
      "thickness2": {
        "anyOf": [
          {
            "$ref": "#/$defs/LengthExpr"
          },
          {
            "type": "null"
          }
        ],
        "description": "With `thin` and `side: two_sides`: the thickness outside."
      },
      "thin": {
        "description": "A thin wall along sketch curves instead of solid profiles.",
        "type": "boolean"
      },
      "through_all": {
        "default": null,
        "description": "Extrude through everything in the way.",
        "type": [
          "boolean",
          "null"
        ]
      },
      "to": {
        "$ref": "#/$defs/Point3",
        "description": "Extrude up to this face, vertex or point (To Object)."
      },
      "to_offset": {
        "anyOf": [
          {
            "$ref": "#/$defs/LengthExpr"
          },
          {
            "type": "null"
          }
        ],
        "description": "How far past `to` to go."
      }
    },
    "title": "ExtrudeParams",
    "type": "object"
  },
  "label": "Extrude",
  "output": {
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "description": "What a feature command returns.",
    "properties": {
      "bodies": {
        "description": "Every body after the feature.",
        "items": {
          "type": "string"
        },
        "type": "array"
      },
      "changed_bodies": {
        "description": "Bodies that were there before and now have other geometry.",
        "items": {
          "type": "string"
        },
        "type": "array"
      },
      "created_bodies": {
        "description": "The bodies the feature made.",
        "items": {
          "type": "string"
        },
        "type": "array"
      },
      "feature": {
        "description": "The new feature's id.",
